div.style:
background-image: url('/clinic_appointment/static/description/hospit_border.png');
background-size: 100% 100%;
background-repeat: no-repeat;
min-height: 900px;
padding: 100px;
box-sizing: border-box;

display:flex;
justify-content:space-between;
align-items:flex-start;
gap:40px;
margin-top:20px;
margin-bottom:22px;
background:#EAF4FF;  /* 🔥 softer light blue */
padding:30px 36px;
border-radius:14px;
box-shadow:0 4px 10px rgba(0,0,0,0.05); /* 🔥 lighter shadow */

/* 🔥 LIGHT SHADED BORDER */
border:8px solid transparent;
background-image:
    linear-gradient(#EAF4FF, #EAF4FF),
    linear-gradient(135deg, #5AA9FF, #5CD68D, #5BC0DE, #FFD966);
background-origin:border-box;
background-clip:padding-box, border-box;

display:inline-block;
border-radius:16px;

border:5px solid transparent;
background-image:
    linear-gradient(#EAF4FF, #EAF4FF),
    linear-gradient(135deg, #2c7be5, #28a745, #17a2b8, #ffc107);
background-origin:border-box;
background-clip:padding-box, border-box;

position:relative;
display:inline-block;
background:#ffffff;
padding:4px 8px;
border-radius:2px;
cursor:pointer;
font-weight:bold;
font-size:14px;   /* ✅ increased font */
min-width:90px;
text-align:center;
border:1px solid #dcdcdc;
box-shadow:0 1px 4px rgba(0,0,0,0.1);

ul.style:
display:none;
position:absolute;
top:100%;
left:0;
list-style:none;
margin:0;
padding:2px 0;
background:#ffffff;
border:1px solid #e0e0e0;
border-radius:2px;
box-shadow:0 2px 6px rgba(0,0,0,0.1);
z-index:999;
width:max-content;      /* 🔥 KEY FIX */
min-width:180px;        /* 🔥 ensures proper size */

